<?php require_once __DIR__.'/../includes/functions.php';require_role(['admin','finance']);$rows=db()->query("SELECT p.*,o.order_number,u.name FROM payments p JOIN orders o ON o.id=p.order_id JOIN customers c ON c.id=o.customer_id JOIN users u ON u.id=c.user_id ORDER BY p.created_at DESC")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){db()->prepare("UPDATE payments SET status=? WHERE id=?")->execute([$_POST['status'],(int)$_POST['id']]);redirect('payments.php');}?><!doctype html><html lang="id"><head><?php include __DIR__.'/../includes/head.php';?></head><body><?php include __DIR__.'/../includes/header.php';?><main class="content"><h1>Payments</h1><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['order_number'])?></td><td><?=e($r['name'])?></td><td>Rp <?=number_format($r['amount'],0,',','.')?></td><td><?=e($r['status'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>pending</option><option>verified</option><option>rejected</option></select><button>Update</button></form></td></tr><?php endforeach;?></table></div></main></body></html>